import json,numpy as np
r=json.load(open('tmp/plecs/full.json'));t=np.array(r['Time']);y=np.array(r['Values']);sel=t>=0.1;t=t[sel];y=y[:,sel];av=lambda x:np.trapezoid(x,t)/(t[-1]-t[0]);v=y[:3];i=y[3:6];vo=y[6];print('Vdc',av(vo),'pp',np.ptp(vo),'Po',av(vo**2/32),'Pin',av((v*i).sum(axis=0)));print('I RMS',np.sqrt(av(i*i)));print('PF',av(v*i)/np.sqrt(av(v*v)*av(i*i)));print('G',av(y[16]));N=40000;tu=0.1+np.arange(N)*.02/N;iu=np.array([np.interp(tu,t,z) for z in i]);a=np.abs(np.fft.rfft(iu,axis=1))*2/N;print('THD2-40',np.sqrt(sum(a[:,16*h]**2 for h in range(2,41)))/a[:,16]*100);print('imax',abs(i).max());
